steps.raw:
SELECT PetType, AVG(pet_age) AS avg_lifespan, MAX(pet_age) AS max_lifespan
FROM Pets
GROUP BY PetType;

SELECT PetType, AVG(weight) AS avg_weight
FROM Pets
GROUP BY PetType;

SELECT car_makers.Id, car_makers.FullName, model_list.Model
FROM car_makers
JOIN model_list ON car_makers.Id = model_list.Maker;

SELECT country_code, COUNT(*) AS player_count
FROM players
GROUP BY country_code;

SELECT Episode, Rating, Share, 18_49_Rating_Share, Viewers_m, Weekly_Rank, Air_Date, Channel
FROM TV_series
ORDER BY Rating DESC;

SELECT treatment_type_code, SUM(cost_of_treatment) AS total_cost
FROM Treatments
GROUP BY treatment_type_code;

SELECT t.date_of_treatment, p.first_name, p.last_name
FROM Treatments t
JOIN Professionals p ON t.professional_id = p.professional_id;

SELECT t.cost_of_treatment, tt.treatment_type_description
FROM Treatments t
JOIN Treatment_Types tt ON t.treatment_type_code = tt.treatment_type_code;

SELECT p.property_id, r.property_type_description
FROM Properties p
JOIN Ref_Property_Types r ON p.property_type_code = r.property_type_code;
